import styles from "./queue-display.module.less";
import { useTranslation } from "react-i18next";
import { TodayHelper, multipleClassNames } from "@/core/helpers";
import { CSSProperties, useCallback, useEffect, useMemo, useState } from "react";
import AutoSizedText from "@/core/components/primitives/auto-sized-text/auto-sized-text";
import { useAspectRatioCategory, useHashState, useOpeningHoursForDate } from "@/core/hooks";
import { AnimatePresence, motion } from "framer-motion";
import { capitalizeFirstLetter } from "@/core/helpers";

import {
  QueueDisplayCategoryTitle,
  QueueDisplayColumn,
  QueueDisplayDataCategory,
  QueueDisplayRide,
  QueueDisplayRideBlock,
  useGroupedAndSortedRides,
} from "./use-grouped-and-sorted-rides";
import { z } from "zod";
import { existingThemes } from "@/core/types";
import { getRideStoppageInfo } from "@/core/helpers/get-ride-stoppage-info";
import { chunk } from "lodash-es";
import { PlcQueueStoppageFlag } from "@parksandresorts/webapiproxy-types";

/** Settings that can be adjusted through URL hash parameters */
const queueDisplayHashStateSchema = z.object({
  /** Time between pages (if several) (default is `10` seconds) */
  interval: z.number().optional(),
  /**
   * Maximum number of columns per slide, empty columns will never be shown
   * Default values are set based on aspect ratio of the iframe in Blocks (1 or 2)
   */
  columns: z.number().optional(),
  /**
   * Number of rows in column (only ride rows count)
   * Default values are set based on aspect ratio of the iframe in Blocks (9, 12 or 15)
   * The height of the display header is set to the equivalent of 2 rows so that font sizes are proportional
   */
  rows: z.number().optional(),
  /** Color theme */
  theme: z.enum(existingThemes).optional(),
});

export type QueueDisplayProps = {
  contentfulId: string;
  listBlock: {
    listObjects: QueueDisplayRideBlock[];
  };
};

export function QueueDisplay({ contentfulId, listBlock }: QueueDisplayProps) {
  const [hashParams] = useHashState(queueDisplayHashStateSchema);
  const {
    theme,
    interval: pageChangeIntervalFromHash,
    columns: columnsFromHash,
    rows: rowsPerColumnFromHash,
  } = hashParams;
  const { t } = useTranslation();
  const [wrapperRef, setWrapperRef] = useState<HTMLElement | null>(null);
  const wrapperAspectRatio = useAspectRatioCategory(wrapperRef);

  const now = TodayHelper.getNow();
  const openingHours = useOpeningHoursForDate(now);
  const updatedData = useGroupedAndSortedRides(listBlock.listObjects, openingHours);
  const [columnData, setColumnData] = useState<QueueDisplayColumn[]>([]);
  const [currentPage, setCurrentPage] = useState(0);
  const pageChangeInterval = pageChangeIntervalFromHash || 10;
  const [countdown, setCountdown] = useState(pageChangeInterval);
  const [countdownStartTime, setCountdownStartTime] = useState(now);

  /* Set pagination position and default layout settings based on aspect ratio */
  const [paginationPosition, defaultColumnsPerSlide, defaultRowsPerColumn] = useMemo(() => {
    const fewRows = 8;
    const severalRows = 11;
    const manyRows = 14;

    switch (wrapperAspectRatio) {
      case "portrait":
        return ["bottom", 1, manyRows] as const;
      case "classic":
      case "square":
        return ["bottom", 1, severalRows] as const;
      case "fourThree":
        return ["bottom", 1, fewRows] as const;
      case "landscape":
        return ["top", 2, severalRows] as const;
      case "sixteenNine":
      case "widescreen":
      case "twentyoneNine":
      case "ultrawide":
      default:
        return ["top", 2, fewRows] as const;
    }
  }, [wrapperAspectRatio]);

  /* Maximum number of columns per slide
   * If not enough columns with data to display, it will only display as many columns as it has data for,
   * so that there is no empty space */
  const displayColumnsPerSlide = columnsFromHash || defaultColumnsPerSlide;
  /* Number of ride rows per column */
  const displayRowsPerColumn = rowsPerColumnFromHash || defaultRowsPerColumn;

  const numberOfPages = Math.ceil(columnData.length / displayColumnsPerSlide);

  const paginationRows = numberOfPages > 1 && paginationPosition === "bottom" ? 1 : 0;
  const headerRows = 2;
  const columnHeaderRows = 1; // Nowadays, we always have only one header row per column
  const totalRows = headerRows + displayRowsPerColumn + columnHeaderRows + paginationRows;

  /** Split rides into columns and rows. Column splits are decided by categories and `displayRowsPerColumn` */
  const getColumnData = useCallback(
    (rideCategories: QueueDisplayDataCategory[]) => {
      return rideCategories.flatMap((category) => {
        // Order by status
        const allRides = [
          ...category.rides.open,
          ...category.rides.temporarilyClosed,
          ...category.rides.notOperational,
        ];

        return chunk(allRides, displayRowsPerColumn).map((rows) => ({
          columnTitle: category.category,
          rows,
        }));
      });
    },
    [displayRowsPerColumn],
  );

  const restartSlider = useCallback(() => {
    if (updatedData === undefined) return;
    setColumnData(getColumnData(updatedData));
    setCurrentPage(0);
    setCountdownStartTime(TodayHelper.getNow());
    setCountdown(pageChangeInterval);
  }, [updatedData, getColumnData, pageChangeInterval]);

  /** Restart slider as soon as we have data */
  useEffect(() => {
    if (columnData.length === 0 && updatedData !== undefined) {
      restartSlider();
    }
    return undefined;
  }, [updatedData, columnData.length, restartSlider]);

  /** Update data and restart slider when layout changes */
  useEffect(() => {
    restartSlider();
  }, [totalRows, displayRowsPerColumn, displayColumnsPerSlide]);

  /** Show next slide */
  useEffect(() => {
    // Queue time data from database is not yet available
    if (updatedData === undefined) return undefined;

    // Change slide when countdown is less than 0, otherwise it will change the slide too fast and not show 0 in the countdown
    if (countdown < 0) {
      // On last page, update slides with newest ride data and restart slider
      if (currentPage + 1 === numberOfPages) {
        setCurrentPage(0);
        setColumnData(getColumnData(updatedData));
      } else {
        setCurrentPage((index) => (index + 1) % columnData.length);
      }
      setCountdownStartTime(TodayHelper.getNow());
      setCountdown(pageChangeInterval);
    }
  }, [countdown, currentPage, numberOfPages, columnData.length, updatedData, getColumnData, pageChangeInterval]);

  /** Countdown for next slide */
  useEffect(() => {
    if (columnData.length === 0) return undefined;

    const intervalId = setInterval(() => {
      const elapsedTime = TodayHelper.getNow().valueOf() - countdownStartTime.valueOf();
      const secondsRemaining = pageChangeInterval - Math.floor(elapsedTime / 1000);
      setCountdown(secondsRemaining);
    }, 1_000);

    return () => clearInterval(intervalId);
  }, [columnData.length, countdownStartTime, pageChangeInterval]);

  /** Forces rerender so that DOM gets all correct values from hash paramms */
  if (typeof window === "undefined") return null;

  return (
    <section
      data-contentful-id={contentfulId}
      className={multipleClassNames(
        styles.wrapper,
        styles.gridForAutoSizedText,
        theme && `component-theme component-theme-${theme} ${theme}`,
      )}
      style={{ gridTemplateRows: `repeat(${totalRows}, 1fr)` }}
      ref={setWrapperRef}
    >
      {/* HEADER */}
      <div
        className={multipleClassNames(
          styles.header,
          styles.rowProportion,
          styles.columnProportion,
          styles.gridForAutoSizedText,
        )}
      >
        <div
          className={multipleClassNames(styles.swedishHeadline, styles.gridForAutoSizedText)}
          data-has-top-pagination={numberOfPages > 1 && paginationPosition === "top"}
        >
          <AutoSizedText
            text={t("queueDisplayExpectedQueueTimeRide", { lng: "sv" })}
            fontWeight="var(--common-font-weight-xl)"
            justifyContent="flex-start"
            alignItems="flex-end"
            padding="2 0"
            paddingMode="dynamic"
          />
        </div>
        {/* PAGINATION */}
        {numberOfPages > 1 && paginationPosition === "top" && (
          <div className={multipleClassNames(styles.gridForAutoSizedText)}>
            <Pagination
              position={paginationPosition}
              currentPage={currentPage}
              numberOfPages={numberOfPages}
              countdown={countdown}
            />
          </div>
        )}
        <div className={multipleClassNames(styles.englishHeadline, styles.englishText, styles.gridForAutoSizedText)}>
          <div className={multipleClassNames(styles.gridForAutoSizedText)}>
            <AutoSizedText
              text={t("queueDisplayExpectedQueueTimeRide", { lng: "en" })}
              fontWeight="var(--common-font-weight-xl)"
              justifyContent="flex-start"
              alignItems="flex-start"
              padding="2 0"
              paddingMode="dynamic"
            />
          </div>
        </div>
      </div>

      {/* SLIDER */}
      {columnData && (
        <div
          id="queueDisplaySlider"
          className={multipleClassNames(styles.slider, styles.gridForAutoSizedText)}
          style={{ gridRow: `span ${displayRowsPerColumn + columnHeaderRows}` }}
        >
          <AnimatePresence>
            <motion.div
              key={`page-${currentPage}`}
              className={multipleClassNames(styles.slide, styles.gridForAutoSizedText)}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 3, type: "spring" }}
            >
              <Slide
                columns={displayColumnsPerSlide}
                columnData={columnData}
                currentPage={currentPage}
                displayColumnRows={displayRowsPerColumn}
              />
            </motion.div>
          </AnimatePresence>
        </div>
      )}

      {/* PAGINATION */}
      {numberOfPages > 1 && paginationPosition === "bottom" && (
        <Pagination
          position={paginationPosition}
          currentPage={currentPage}
          numberOfPages={numberOfPages}
          countdown={countdown}
        />
      )}
    </section>
  );
}

/** If more than one page, show pagination info and countdown to next page */
const Pagination = ({
  position,
  currentPage,
  numberOfPages,
  countdown,
}: {
  position: "top" | "bottom";
  currentPage: number;
  numberOfPages: number;
  countdown: number;
}) => {
  const { t } = useTranslation();
  const [paginationWrapperRef, setPaginationWrapperRef] = useState<HTMLDivElement | null>(null);
  const fontWeight = "var(--common-font-weight-l)";
  /** Save size in state to prevent flicker due to icon wrapper initially being the wrong size */
  const [countdownWidth, setCountdownWidth] = useState<number>(0);
  useEffect(() => {
    setCountdownWidth(paginationWrapperRef?.clientHeight || 0);
  }, [paginationWrapperRef]);
  return (
    <div
      className={multipleClassNames(
        styles.paginationWrapper,
        styles[`pagination${capitalizeFirstLetter(position)}`],
        styles.gridForAutoSizedText,
      )}
      style={{ gridTemplateColumns: `1fr ${countdownWidth}px` }}
      ref={setPaginationWrapperRef}
    >
      <div className={multipleClassNames(styles.rowProportion, styles.gridForAutoSizedText)}>
        <div className={multipleClassNames(styles.gridForAutoSizedText)}>
          <AutoSizedText
            text={t("queueDisplayPagination", {
              lng: "sv",
              currentPage: currentPage + 1,
              numberOfPages: numberOfPages,
            })}
            fontWeight={fontWeight}
            justifyContent="flex-end"
            alignItems="flex-end"
            padding="0"
          />
        </div>
        <div className={multipleClassNames(styles.gridForAutoSizedText, styles.englishText)}>
          <AutoSizedText
            text={t("queueDisplayPagination", {
              lng: "en",
              currentPage: currentPage + 1,
              numberOfPages: numberOfPages,
            })}
            fontWeight={fontWeight}
            justifyContent="flex-end"
            alignItems="flex-start"
            padding="0"
          />
        </div>
      </div>
      <div className={multipleClassNames(styles.rowProportion, styles.gridForAutoSizedText)}>
        <div className={multipleClassNames(styles.gridForAutoSizedText)}>
          <AutoSizedText text={Math.max(countdown, 0).toString()} fontWeight={fontWeight} padding="0" />
        </div>
      </div>
    </div>
  );
};

/** Header row for each column */
const ColumnHeader = ({ title }: { title: QueueDisplayCategoryTitle }) => {
  const { t } = useTranslation();

  const fontWeight = "var(--common-font-weight-l)";
  const justifyContentTitle = "flex-start";
  const justifyContentInfo = "center";
  const padding = "10 2";

  const titleText =
    title?.sv && title?.en ? `${title.sv} / ${title.en}` : t("queueDisplayRideHeaderSweEng", { lng: "sv" });

  return (
    <div className={multipleClassNames(styles.columnProportion, styles.gridForAutoSizedText, styles.categoryOpenRides)}>
      <div className={multipleClassNames(styles.gridForAutoSizedText)}>
        <AutoSizedText
          text={titleText}
          fontWeight={fontWeight}
          justifyContent={justifyContentTitle}
          padding={padding}
          paddingMode="dynamic"
        />
      </div>
      <div className={multipleClassNames(styles.gridForAutoSizedText)}>
        <AutoSizedText
          text={t("queueDisplayStatusHeader", { lng: "sv" })}
          fontWeight={fontWeight}
          justifyContent={justifyContentInfo}
          padding={padding}
          paddingMode="dynamic"
        />
      </div>
    </div>
  );
};

const RideRow = ({ ride }: { ride: QueueDisplayRide }) => {
  const { t } = useTranslation();
  const { rideId, rideTitle, displayState } = ride;

  const [wrapperRef, setWrapperRef] = useState<HTMLDivElement | null>(null);
  const rideRowPadding = wrapperRef?.clientHeight ? wrapperRef.clientHeight * 0.1 : 0;
  const [stoppageWrapperRef, setStoppageWrapperRef] = useState<HTMLDivElement | null>(null);
  /** Set width same as wrapper height to make icon wrapper square and look good no matter how narrow or wide the column is
   * Only calculate icon width when needed to prevent flicker due to icon wrapper initially being the wrong size */
  const iconWidth = useMemo(() => {
    return stoppageWrapperRef?.clientHeight ? stoppageWrapperRef.clientHeight - rideRowPadding * 2 : 0;
  }, [stoppageWrapperRef, rideRowPadding]);
  const [iconRef, setIconRef] = useState<HTMLDivElement | null>(null);

  const { stoppageIcon, stoppageTextSv, stoppageTextEn } =
    displayState.state === "CLOSED"
      ? getRideStoppageInfo(displayState.queueData.queueState, displayState.queueData.stoppageStatus, t)
      : displayState.state !== "QUEUE_TIME"
      ? getRideStoppageInfo("temporarilyClosed", PlcQueueStoppageFlag.OTHER_STOPPAGE, t)
      : { stoppageIcon: undefined, stoppageTextSv: "", stoppageTextEn: "" };
  const subtitle =
    displayState.state === "OPENS_SOON"
      ? t("queueDisplayRideOpensOnSweEng", { time: displayState.openingTime })
      : displayState.state === "QUEUE_TIME"
      ? displayState.closingTime && t("queueDisplayRideClosesOnSweEng", { time: displayState.closingTime })
      : null;

  const fontWeight = "var(--common-font-weight-xl)";
  const justifyContentTitle = "flex-start";
  const justifyContentInfo = displayState.state === "QUEUE_TIME" ? "center" : "flex-start";
  const padding = "0";

  return (
    <div
      key={rideId}
      className={multipleClassNames(styles.rideRow, styles.columnProportion, styles.gridForAutoSizedText)}
      ref={setWrapperRef}
    >
      {/* Ride Title */}
      <div
        className={multipleClassNames(
          styles.rideTitle,
          displayState.state === "QUEUE_TIME" ? styles.openRide : styles.closedRide,
          styles.gridForAutoSizedText,
        )}
        style={{ "--ride-title-padding": `${rideRowPadding}px` } as CSSProperties}
      >
        <div className={styles.gridForAutoSizedText}>
          <AutoSizedText
            text={rideTitle}
            justifyContent={justifyContentTitle}
            fontWeight={fontWeight}
            padding={padding}
            paddingMode="dynamic"
          />
        </div>
        {subtitle && (
          <div className={styles.gridForAutoSizedText}>
            <AutoSizedText
              text={subtitle}
              justifyContent={justifyContentTitle}
              fontWeight={fontWeight}
              padding={padding}
              paddingMode="dynamic"
            />
          </div>
        )}
      </div>

      {/* Ride Info - Open ride */}
      {displayState.state === "QUEUE_TIME" ? (
        <div
          className={multipleClassNames(styles.rideInfo, styles.openRide, styles.gridForAutoSizedText)}
          style={{ padding: `${rideRowPadding}px` }}
        >
          <div className={styles.gridForAutoSizedText}>
            <AutoSizedText
              text={displayState.queueData.queueTime}
              justifyContent={justifyContentInfo}
              fontWeight={fontWeight}
              padding={padding}
              paddingMode="dynamic"
            />
          </div>
        </div>
      ) : (
        // Ride Info - Closed ride
        <div
          className={multipleClassNames(styles.rideInfo, styles.closedRide, styles.gridForAutoSizedText)}
          style={{
            padding: `${rideRowPadding}px`,
            gap: `${rideRowPadding}px`,
            gridTemplateColumns: `${iconWidth}px 1fr`,
          }}
          ref={setStoppageWrapperRef}
        >
          <div className={multipleClassNames(styles.gridForAutoSizedText)} ref={setIconRef}>
            <AutoSizedText wrapperElement={iconRef} text="" fontWeight={fontWeight} icon={stoppageIcon} />
          </div>
          <div className={multipleClassNames(styles.rowProportion, styles.gridForAutoSizedText)}>
            <div className={styles.gridForAutoSizedText}>
              <AutoSizedText
                text={stoppageTextSv}
                justifyContent="flex-start"
                alignItems="flex-end"
                fontWeight={fontWeight}
                padding="0"
              />
            </div>
            <div className={multipleClassNames(styles.gridForAutoSizedText, styles.closedRideEnglish)}>
              <AutoSizedText
                text={stoppageTextEn}
                justifyContent="flex-start"
                alignItems="flex-start"
                fontWeight={fontWeight}
                padding="0"
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const Column = ({
  columnData,
  page,
  displayColumnRows,
}: {
  columnData: QueueDisplayColumn;
  page: number;
  displayColumnRows: number;
}) => {
  return (
    <div
      className={multipleClassNames(styles.column, styles.gridForAutoSizedText)}
      style={{ gridTemplateRows: `0.8fr repeat(${displayColumnRows}, 1fr)` }}
    >
      <ColumnHeader title={columnData.columnTitle} />
      {columnData.rows.map((ride, index) => (
        <div key={`page-${page}-${ride.rideId}-row-${index}`} className={styles.gridForAutoSizedText}>
          <RideRow ride={ride} />
        </div>
      ))}
    </div>
  );
};

const Slide = ({
  columns,
  columnData,
  currentPage,
  displayColumnRows,
}: {
  columns: number;
  columnData: QueueDisplayColumn[];
  currentPage: number;
  displayColumnRows: number;
}) => {
  const slides: JSX.Element[] = [];
  for (let i = 0; i < columnData.length; i += columns) {
    const columnsForSlide = columnData.slice(i, i + columns);
    slides.push(
      <div
        className={multipleClassNames(styles.columnWrapper, styles.gridForAutoSizedText)}
        key={`slide-${i / columns}`}
        style={{ gridTemplateColumns: `repeat(${columnsForSlide.length}, 1fr)` }}
      >
        {columnsForSlide.map((col, colIdx) => (
          <Column
            key={`column-${i + colIdx}`}
            columnData={col}
            page={i + colIdx}
            displayColumnRows={displayColumnRows}
          />
        ))}
      </div>,
    );
  }

  return slides[currentPage] ? [slides[currentPage]] : null;
};
