import {
  QueueDisplayQueueState,
  QueueDisplayRideStoppageStatus,
} from "@/core/components/modules/queue-display/use-grouped-and-sorted-rides";
import { IconName } from "@/core/components/primitives/icon/icon";
import { exhaustiveCheck } from "../helpers";
import { PlcQueueStoppageFlag } from "@parksandresorts/webapiproxy-types";
import { TFunction } from "i18next";

/**
 * React hook to get stoppage text and icon for a ride based on its state and stoppage status.
 */
export function getRideStoppageInfo(
  rideState: QueueDisplayQueueState,
  rideStoppageStatus: QueueDisplayRideStoppageStatus,
  t: TFunction,
): {
  stoppageTextCurrentLocale: string;
  stoppageTextSv: string;
  stoppageTextEn: string;
  stoppageIcon: IconName | undefined;
} {
  const stoppageIcon = ((): IconName | undefined => {
    if (rideState === "open") {
      return undefined;
    }

    switch (rideStoppageStatus) {
      // Temporarily closed
      case PlcQueueStoppageFlag.TECHNICAL_STOPPAGE:
      case PlcQueueStoppageFlag.SANITATION_STOPPAGE:
      case PlcQueueStoppageFlag.OTHER_STOPPAGE:
        return "hourglassTop";
      case PlcQueueStoppageFlag.CONCERT_STOPPAGE:
        return "mic";
      case PlcQueueStoppageFlag.WEATHER_STOPPAGE:
        return "thunderstorm";
      // Closed
      case PlcQueueStoppageFlag.CLOSED_REST_OF_DAY:
      case PlcQueueStoppageFlag.TECHNICAL_STOPPAGE_REST_OF_DAY:
      case PlcQueueStoppageFlag.ADVANCE_CLOSURE:
      case PlcQueueStoppageFlag.POST_STOPPAGE_REGISTRATION:
      case PlcQueueStoppageFlag.CLOSED_UNTIL_FURTHER_NOTICE:
        return "hotel";

      case undefined:
      case PlcQueueStoppageFlag.MESSAGE_READ:
        // These are unhandled
        return undefined;
      default:
        return exhaustiveCheck(rideStoppageStatus);
    }
  })();

  const stoppageTexts = (() => {
    if (rideState === "open") {
      return { stoppageTextCurrentLocale: "", stoppageTextSv: "", stoppageTextEn: "" };
    }

    const getStoppageText = (language: "sv" | "en" | undefined) => {
      return t(`queueTimeStoppageTexts.${rideStoppageStatus}`, {
        lng: language,
        defaultValue:
          rideState === "temporarilyClosed"
            ? t("queueDisplayTemporarilyClosed", { lng: language })
            : t("queueDisplayNotOperational", { lng: language }),
      });
    };

    const stoppageTextCurrentLocale = getStoppageText(undefined);
    const stoppageTextSv = getStoppageText("sv");
    const stoppageTextEn = getStoppageText("en");

    return { stoppageTextCurrentLocale, stoppageTextSv, stoppageTextEn };
  })();

  return { ...stoppageTexts, stoppageIcon };
}
