const MOCKED_OPENING_TIME = "08:00:00+0200";
const MOCKED_CLOSING_TIME = "22:00:00+0200";

type QueueDisplayHashParams = HashParams<{
  hashInterval: number | undefined;
  hashColumns: number | undefined;
  hashRows: number | undefined;
  hashTheme: string;
}>;

const meta = {
  title: "Modules/Queue Display",
  component: QueueDisplay,
  parameters: {
    chromatic: extraLargeDesktopOnlyMode,
  },
  decorators: [setHashParams, withMockedDate, withQueryProvider, withEmptyStaticConfigProvider],
  argTypes: {
    hashInterval: {
      control: {
        type: "number",
        min: 3,
        max: 30,
        step: 1,
      },
    },
    hashColumns: {
      control: {
        type: "number",
        min: 1,
        max: 5,
        step: 1,
      },
    },
    hashRows: {
      control: {
        type: "number",
        min: 3,
        max: 30,
        step: 1,
      },
    },
    hashTheme: {
      options: existingThemes,
      control: {
        type: "select",
      },
    },
  },
  render: (args) => renderQueueDisplay(args),
} satisfies Meta<WithMockedDate<WithHashParams<typeof QueueDisplay, QueueDisplayHashParams>>>;

