/** Wrapper to display aspect ratios of container, to show default values */
const AspectRatioWrapper = ({
  children,
  aspectRatio,
  label,
  width,
  height,
}: {
  children: React.ReactNode;
  aspectRatio: string;
  label: string;
  width?: string;
  height?: string;
}) => (
  <div style={{ padding: "20px", background: "#f5f5f5", height: "100vh", width: "100vw", boxSizing: "border-box" }}>
    <style>{`
      /* Override styling for taking up the whole window */
      .queue-display-container [class*="queue-display-module--wrapper"] {
        width: 100% !important;
        height: 100% !important;
      }
    `}</style>
    <div
      style={{
        marginBottom: "10px",
        fontSize: "14px",
        fontWeight: "bold",
        color: "#333",
      }}
    >
      <span>Shows default values for {label}</span>
      <br />
      <span>Values are set in Controls</span>
    </div>
    <div
      style={{
        width: "100%",
        height: "90%",
      }}
    >
      <div
        className="queue-display-container"
        style={{
          aspectRatio,
          width,
          height,
          maxWidth: "100%",
          maxHeight: "100%",
          border: "2px solid #ddd",
          borderRadius: "8px",
          overflow: "hidden",
          background: "white",
          boxShadow: "0 4px 8px rgba(0,0,0,0.1)",
        }}
      >
        {children}
      </div>
    </div>
  </div>
);
