import { useEffect, useState } from "react";

export type AspectRatioCategory =
  | "square"
  | "fourThree"
  | "sixteenNine"
  | "twentyoneNine"
  | "portrait"
  | "classic"
  | "landscape"
  | "widescreen"
  | "ultrawide";

// Fixed aspect ratios and tolerance
const RATIO_SQUARE = 1;
const RATIO_FOUR_THREE = 4 / 3;
const RATIO_SIXTEEN_NINE = 16 / 9;
const RATIO_TWENTYONE_NINE = 21 / 9;
const TOLERANCE = 0.05; // 5% tolerance for aspect ratio matching

const SQUARE_MAX = RATIO_SQUARE * (1 + TOLERANCE);
const FOUR_THREE_MIN = RATIO_FOUR_THREE * (1 - TOLERANCE);
const FOUR_THREE_MAX = RATIO_FOUR_THREE * (1 + TOLERANCE);
const SIXTEEN_NINE_MIN = RATIO_SIXTEEN_NINE * (1 - TOLERANCE);
const SIXTEEN_NINE_MAX = RATIO_SIXTEEN_NINE * (1 + TOLERANCE);
const TWENTY_ONE_MIN = RATIO_TWENTYONE_NINE * (1 - TOLERANCE);
const TWENTY_ONE_MAX = RATIO_TWENTYONE_NINE * (1 + TOLERANCE);

function getAspectRatioCategory(element: HTMLElement): AspectRatioCategory {
  const { width, height } = element.getBoundingClientRect();
  const ratio = width / height;

  if (ratio < RATIO_SQUARE) return "portrait"; // Smaller than 1:1
  if (ratio < SQUARE_MAX) return "square"; // 1:1
  if (ratio < FOUR_THREE_MIN) return "classic"; // Between 1:1 and 4:3
  if (ratio < FOUR_THREE_MAX) return "fourThree"; // 4:3
  if (ratio < SIXTEEN_NINE_MIN) return "landscape"; // Between 4:3 and 16:9
  if (ratio < SIXTEEN_NINE_MAX) return "sixteenNine"; // 16:9
  if (ratio < TWENTY_ONE_MIN) return "widescreen"; // Between 16:9 and 21:9
  if (ratio < TWENTY_ONE_MAX) return "twentyoneNine"; // 21:9
  return "ultrawide"; // Bigger than 21:9
}

/**
 * React hook to determine the aspect ratio category of an element.
 *
 * Useful for styling based on aspect ratio instead of, or as a complement to, media queries.
 * This hook observes the element's size and updates the aspect ratio category accordingly.
 * It returns the most common exact aspect ratios, or categories between these.
 *
 * @returns {AspectRatioCategory} The aspect ratio category of the element:
 * - `portrait` Smaller than 1:1
 * - `square` 1:1
 * - `classic` Between 1:1 and 4:3
 * - `fourThree` 4:3
 * - `landscape` Between 4:3 and 16:9
 * - `sixteenNine` 16:9
 * - `widescreen` Between 16:9 and 21:9
 * - `twentyoneNine` 21:9
 * - `ultrawide` Bigger than 21:9
 *
 * @remarks
 * - This hook uses ResizeObserver to monitor changes in the element's size and updates the aspect ratio category accordingly.
 * - It is important to ensure that the element is available when the hook is used, otherwise it will not work correctly.
 *   Use `useState` and not `useRef` to make sure the wrapper element is available.
 *
 * @example
 *   ```tsx
 *      const [wrapperRef, setWrapperRef] = useState<HTMLElement | null>(null);
 *      const wrapperAspect = useAspectRatioCategory(wrapperRef);
 *   ```
 */
export function useAspectRatioCategory(element: HTMLElement | null): AspectRatioCategory {
  const [aspect, setAspect] = useState<AspectRatioCategory>("portrait");

  useEffect(() => {
    if (!element) return undefined;

    const updateAspect = () => setAspect(getAspectRatioCategory(element));
    updateAspect();

    const observer = new ResizeObserver(updateAspect);
    observer.observe(element);
    return () => observer.disconnect();
  }, [element]);

  return aspect;
}
